from typing import List, Dict
from collections import deque

class EightPuzzle:
    def __init__(self, initial_state: List[List[int]]):
        self.initial_state = initial_state
        self.goal_state = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]

    def find_blank(self, state: List[List[int]]) -> Tuple[int, int]:
        for i in range(3):
            for j in range(3):
                if state[i][j] == 0:
                    return (i, j)

    def move(self, state: List[List[int]], direction: str) -> List[List[int]]:
        blank_i, blank_j = self.find_blank(state)
        if direction == 'up' and blank_i > 0:
            state[blank_i][blank_j], state[blank_i - 1][blank_j] = state[blank_i - 1][blank_j], state[blank_i][blank_j]
        elif direction == 'down' and blank_i < 2:
            state[blank_i][blank_j], state[blank_i + 1][blank_j] = state[blank_i + 1][blank_j], state[blank_i][blank_j]
        elif direction == 'left' and blank_j > 0:
            state[blank_i][blank_j], state[blank_i][blank_j - 1] = state[blank_i][blank_j - 1], state[blank_i][blank_j]
        elif direction == 'right' and blank_j < 2:
            state[blank_i][blank_j], state[blank_i][blank_j + 1] = state[blank_i][blank_j + 1], state[blank_i][blank_j]
        return state

    def get_possible_moves(self, state: List[List[int]]) -> List[str]:
        possible_moves = []
        blank_i, blank_j = self.find_blank(state)
        if blank_i > 0:
            possible_moves.append('up')
        if blank_i < 2:
            possible_moves.append('down')
        if blank_j > 0:
            possible_moves.append('left')
        if blank_j < 2:
            possible_moves.append('right')
        return possible_moves

    def solve(self) -> List[str]:
        open_list = deque([(self.initial_state, [])])
        visited = set([str(self.initial_state)])

        while open_list:
            current_state, path = open_list.popleft()

            if current_state == self.goal_state:
                return path

            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state.copy(), move)
                new_state_str = str(new_state)

                if new_state_str not in visited:
                    visited.add(new_state_str)
                    open_list.append((new_state, path + [move]))

        return []

